  1→import express, { Request, Response } from "express";
  2→import { query } from "@anthropic-ai/claude-agent-sdk";
  3→import { Langfuse } from "langfuse";
  4→import { mkdirSync, writeFileSync, existsSync } from "fs";
  5→import { homedir } from "os";
  6→import { join } from "path";
  7→import type { QueryRequest, HealthResponse } from "./types.js";
  8→
  9→// Claude CLI requires certain directories/files under ~/.claude to exist.
 10→// The container uses a tmpfs mount at ~/.claude which starts empty, so we
 11→// create the expected structure at startup.
 12→const claudeDir = join(homedir(), ".claude");
 13→for (const sub of ["debug", "projects"]) {
 14→  const dir = join(claudeDir, sub);
 15→  if (!existsSync(dir)) {
 16→    mkdirSync(dir, { recursive: true });
 17→  }
 18→}
 19→const settingsFile = join(claudeDir, "remote-settings.json");
 20→if (!existsSync(settingsFile)) {
 21→  writeFileSync(settingsFile, "{}");
 22→}
 23→
 24→// Initialize Langfuse if credentials are available (reads from env vars
 25→// LANGFUSE_PUBLIC_KEY, LANGFUSE_SECRET_KEY, LANGFUSE_BASE_URL automatically)
 26→let langfuse: Langfuse | null = null;
 27→if (process.env.LANGFUSE_PUBLIC_KEY && process.env.LANGFUSE_SECRET_KEY) {
 28→  langfuse = new Langfuse();
 29→  console.log("[sidecar] Langfuse tracing enabled");
 30→}
 31→
 32→const app = express();
 33→app.use(express.json({ limit: "10mb" }));
 34→
 35→const PORT = parseInt(process.env.PORT || "3000", 10);
 36→
 37→let activeAbort: AbortController | null = null;
 38→
 39→app.get("/health", (_req: Request, res: Response) => {
 40→  const response: HealthResponse = { status: "ok" };
 41→  res.json(response);
 42→});
 43→
 44→app.post("/query", async (req: Request, res: Response) => {
 45→  const body = req.body as QueryRequest;
 46→
 47→  if (!body.message || !body.system_prompt) {
 48→    res.status(400).json({ error: "message and system_prompt are required" });
 49→    return;
 50→  }
 51→
 52→  // Set up SSE headers
 53→  res.setHeader("Content-Type", "text/event-stream");
 54→  res.setHeader("Cache-Control", "no-cache");
 55→  res.setHeader("Connection", "keep-alive");
 56→  res.setHeader("X-Accel-Buffering", "no");
 57→  res.flushHeaders();
 58→
 59→  const abortController = new AbortController();
 60→  activeAbort = abortController;
 61→
 62→  // Merge per-request env overrides (e.g. fresh proxy tokens) with process env
 63→  const sdkEnv: Record<string, string> = {};
 64→  for (const [k, v] of Object.entries(process.env)) {
 65→    if (v !== undefined) sdkEnv[k] = v;
 66→  }
 67→  if (body.env) {
 68→    Object.assign(sdkEnv, body.env);
 69→  }
 70→  // Scrub Langfuse credentials so the agent subprocess cannot read them from
 71→  // the inherited environment — matches backend subprocess behaviour.
 72→  // The sidecar's own Langfuse client already holds the credentials internally.
 73→  sdkEnv["LANGFUSE_PUBLIC_KEY"] = "";
 74→  sdkEnv["LANGFUSE_SECRET_KEY"] = "";
 75→
 76→  let responseEnded = false;
 77→
 78→  // Detect client disconnect
 79→  res.on("close", () => {
 80→    if (!responseEnded) {
 81→      abortController.abort();
 82→    }
 83→  });
 84→
 85→  // --- Langfuse tracing setup ---
 86→  // Mirror the backend's session ID handling:
 87→  //   - langfuse_session_id (from frontend for edit/delete) takes priority
 88→  //   - session_id (CLI session from previous turn) as fallback
 89→  const modelName = body.model || process.env.ANTHROPIC_MODEL || "claude-opus-4-6";
 90→  const traceMessage = body.original_message || body.message;
 91→  const traceInput: Record<string, unknown> = {
 92→    message: traceMessage.substring(0, 500),
 93→  };
 94→  if (body.conversation_history && body.conversation_history.length > 0) {
 95→    traceInput.conversation_history = body.conversation_history;
 96→  }
 97→  const trace = langfuse?.trace({
 98→    name: "agent-chat",
 99→    sessionId: body.langfuse_session_id || body.session_id || undefined,
100→    input: traceInput,
101→    metadata: { model: modelName, mode: "container" },
102→  });
103→
104→  // Per-turn usage tracking from stream events
105→  let currentGenUsage: { input?: number; output?: number } = {};
106→  // Accumulated messages for generation input context
107→  const accumulatedMessages: Array<{ role: string; content: unknown }> = [
108→    { role: "user", content: body.message },
109→  ];
110→
111→  try {
112→    const sdkQuery = query({
113→      prompt: body.message,
114→      options: {
115→        model: modelName,
116→        systemPrompt: body.system_prompt,
117→        allowedTools: ["mcp__duckdb__execute_sql"],
118→        permissionMode: "bypassPermissions",
119→        allowDangerouslySkipPermissions: true,
120→        maxTurns: 20,
121→        includePartialMessages: true,
122→        abortController,
123→        env: sdkEnv,
124→        ...(body.mcp_server_url
125→          ? {
126→              mcpServers: {
127→                duckdb: {
128→                  type: "sse" as const,
129→                  url: body.mcp_server_url,
130→                },
131→              },
132→            }
133→          : {}),
134→        ...(body.session_id ? { resume: body.session_id } : {}),
135→      },
136→    });
137→
138→    console.log(
139→      `[sidecar] SDK query started model=${modelName}`
140→    );
141→
142→    for await (const message of sdkQuery) {
143→      if (responseEnded) break;
144→      // Forward each SDK message as an SSE data line
145→      res.write(`data: ${JSON.stringify(message)}\n\n`);
146→
147→      // --- Create Langfuse observations from SDK messages ---
148→      if (!trace) continue;
149→      const msg = message as Record<string, unknown>;
150→
151→      if (msg.type === "stream_event") {
152→        // Capture per-turn token usage from API stream events
153→        const event = (msg.event as Record<string, unknown>) || {};
154→        const eventType = event.type as string;
155→        if (eventType === "message_start") {
156→          const msgData = (event.message as Record<string, unknown>) || {};
157→          const usage = (msgData.usage as Record<string, number>) || {};
158→          currentGenUsage = { input: usage.input_tokens || 0 };
159→        } else if (eventType === "message_delta") {
160→          const usage = (event.usage as Record<string, number>) || {};
161→          currentGenUsage.output = usage.output_tokens || 0;
162→        }
163→      } else if (msg.type === "assistant") {
164→        // Create a generation observation for each assistant turn
165→        const msgObj = (msg.message as Record<string, unknown>) || {};
166→        const content = msgObj.content as unknown[];
167→
168→        const usage =
169→          currentGenUsage.input !== undefined
170→            ? {
171→                input: currentGenUsage.input || 0,
172→                output: currentGenUsage.output || 0,
173→                total:
174→                  (currentGenUsage.input || 0) +
175→                  (currentGenUsage.output || 0),
176→                unit: "TOKENS" as const,
177→              }
178→            : undefined;
179→
180→        const gen = trace.generation({
181→          name: "claude.assistant.turn",
182→          model: (msgObj.model as string) || modelName,
183→          input: { messages: accumulatedMessages.slice(-6) },
184→          output: { content, role: "assistant" },
185→          usage,
186→        });
187→        gen.end();
188→        currentGenUsage = {};
189→
190→        // Accumulate for next turn's input context
191→        accumulatedMessages.push({ role: "assistant", content });
192→      } else if (msg.type === "user") {
193→        // Accumulate tool results for next turn's input context
194→        const msgObj = (msg.message as Record<string, unknown>) || {};
195→        accumulatedMessages.push({
196→          role: "user",
197→          content: msgObj.content,
198→        });
199→      } else if (msg.type === "result") {
200→        // Finalize trace — mirrors backend's finally block:
201→        //   trace_session_id = langfuse_session_id or actual_session_id
202→        const actualSessionId = (msg.session_id as string | undefined) || body.session_id;
203→        const traceSessionId = body.langfuse_session_id || actualSessionId;
204→        trace.update({
205→          ...(traceSessionId ? { sessionId: traceSessionId } : {}),
206→          output: { session_id: actualSessionId },
207→        });
208→      } else if (msg.type === "system") {
209→        // Capture session_id early — only when no langfuse_session_id override
210→        // (matches backend's propagate_attributes(session_id=langfuse_session_id or session_id))
211→        const sessionId = msg.session_id as string | undefined;
212→        if (sessionId && !body.langfuse_session_id) {
213→          trace.update({ sessionId });
214→        }
215→      }
216→    }
217→  } catch (err: unknown) {
218→    const errMsg = err instanceof Error ? err.message : String(err);
219→    // Don't log abort errors — they are expected on client disconnect
220→    if (!(err instanceof Error && err.name === "AbortError")) {
221→      console.error(`[sidecar] SDK error: ${errMsg}`);
222→      if (!responseEnded) {
223→        res.write(
224→          `event: error\ndata: ${JSON.stringify({ type: "error", message: errMsg })}\n\n`
225→        );
226→      }
227→      if (trace) {
228→        trace.update({ output: { error: errMsg } });
229→      }
230→    }
231→  } finally {
232→    activeAbort = null;
233→    responseEnded = true;
234→    res.end();
235→    // Flush Langfuse events before the response is fully closed
236→    if (langfuse) {
237→      await langfuse.flushAsync().catch(() => {});
238→    }
239→    console.log("[sidecar] SSE stream ended");
240→  }
241→});
242→
243→app.post("/stop", (_req: Request, res: Response) => {
244→  if (activeAbort) {
245→    activeAbort.abort();
246→    activeAbort = null;
247→    res.json({ status: "stopped" });
248→  } else {
249→    res.json({ status: "no_active_session" });
250→  }
251→});
252→
253→app.listen(PORT, "0.0.0.0", () => {
254→  console.log(`Sidecar agent server listening on port ${PORT}`);
255→});
